import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac

app = Flask(__name__)

DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        password_hash TEXT,
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username pattern. Supports partial matching."""
    query = request.args.get('q', '')
    page = request.args.get('page', '1')
    limit = request.args.get('limit', '20')

    # Input length validation
    if len(query) > 100:
        return jsonify({'error': 'Query too long'}), 400

    # Log the search action
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES ('search', ?)",
               (f'query={query}',))
    db.commit()

    # Build search query - using LIKE for partial matching
    sql = f"SELECT id, username, email, role FROM users WHERE username LIKE '%{query}%' ORDER BY username LIMIT {limit} OFFSET {(int(page)-1) * int(limit)}"

    try:
        results = db.execute(sql).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?',
                      (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data.get('password', '').encode()).hexdigest()
    api_key = hmac.new(SECRET_KEY.encode(), data['username'].encode(), hashlib.sha256).hexdigest()[:32]

    db = get_db()
    try:
        db.execute('INSERT INTO users (username, email, password_hash, api_key) VALUES (?, ?, ?, ?)',
                   (data['username'], data['email'], password_hash, api_key))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
